bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const q=await pool.query("SELECT s.state,s.revision,s.screen_message_id,s.owner_user_id FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1",['v26nov24invoice']);
 if(q.rows.length!==1)process.exit(62);
 const {state,owner_user_id}=q.rows[0];
 const ref=state.pendingVideoDraft??(state.draft?.listingId?{listingId:state.draft.listingId,revision:state.draft.revision}:null);
 console.log('SESSION',JSON.stringify({screen:state.screen,publishing:state.publishing,reference:!!ref,mode:state.draft?.mode,revision:ref?.revision}));
 if(state.publishing!=='needs_reconcile')process.exit(65);
 if(!ref)process.exit(66);
 const r=await pool.query("SELECT l.status,l.revision, r.status AS receipt_status,r.revision AS receipt_revision,r.paid_message_id IS NOT NULL AS paid,cardinality(r.free_message_ids) AS free_count FROM videobot_listings l LEFT JOIN videobot_post_receipts r ON r.listing_id=l.listing_id AND r.revision=$3 WHERE l.seller_user_id=$1 AND l.listing_id=$2",[owner_user_id,ref.listingId,ref.revision]);
 console.log('EXACT_REF',JSON.stringify(r.rows));
 const u=await pool.query("SELECT count(*)::int AS n FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE l.seller_user_id=$1 AND r.status<>'sent'",[owner_user_id]);
 console.log('UNRESOLVED_RECEIPTS',u.rows[0].n);
 const v=r.rows[0];
 if(v?.status==='published'&&v.receipt_status==='sent'&&v.paid&&[2,3].includes(v.free_count)&&u.rows[0].n===0)process.exit(73);
 if(u.rows[0].n===0)process.exit(74);
 process.exit(75);
}finally{await pool.end()}
JS
